.tradeex-sim-container {
    padding: 24px;
    background: linear-gradient(135deg, #eef2f7 0%, #dce6f0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    color: #1a3a5c;
}

.tradeex-sim-header {
    position: relative;
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: white;
    padding: 36px 30px;
    border-radius: 22px;
    margin-bottom: 26px;
    box-shadow: 0 12px 30px rgba(26,58,92,0.28);
    text-align: center;
    overflow: hidden;
}

.tradeex-sim-header::after {
    content: "";
    position: absolute;
    top: -60px;
    right: -40px;
    width: 220px;
    height: 220px;
    background: radial-gradient(circle, rgba(255,255,255,0.12) 0%, rgba(255,255,255,0) 70%);
    pointer-events: none;
}

.tradeex-sim-header-badge {
    display: inline-block;
    font-size: 0.7rem;
    letter-spacing: 1.5px;
    font-weight: 700;
    text-transform: uppercase;
    background: rgba(255,255,255,0.16);
    border: 1px solid rgba(255,255,255,0.28);
    padding: 5px 14px;
    border-radius: 999px;
    margin-bottom: 14px;
}

.tradeex-sim-header h1 {
    margin: 0 0 8px 0;
    font-size: 1.9rem;
    font-weight: 700;
    letter-spacing: -0.3px;
}

.tradeex-sim-header p {
    margin: 0;
    opacity: 0.9;
    font-size: 1.05rem;
}

/* ---- Round stepper ---- */
.tradeex-sim-stepper {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    max-width: 620px;
    margin: 0 auto 22px auto;
    position: relative;
    padding: 0 10px;
}

.tradeex-sim-stepper::before {
    content: "";
    position: absolute;
    top: 19px;
    left: 12%;
    right: 12%;
    height: 3px;
    background: #c3d2e3;
    z-index: 0;
}

.tradeex-sim-step {
    position: relative;
    z-index: 1;
    display: flex;
    flex-direction: column;
    align-items: center;
    flex: 1;
}

.tradeex-sim-step-dot {
    width: 38px;
    height: 38px;
    border-radius: 50%;
    background: #fff;
    border: 3px solid #c3d2e3;
    color: #90a4bd;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 700;
    font-size: 0.95rem;
    transition: all 0.35s ease;
}

.tradeex-sim-step-label {
    margin-top: 8px;
    font-size: 0.78rem;
    font-weight: 600;
    color: #90a4bd;
    transition: color 0.35s ease;
}

.tradeex-sim-step.is-active .tradeex-sim-step-dot {
    background: linear-gradient(135deg, #2c5f8a, #1a3a5c);
    border-color: #1a3a5c;
    color: #fff;
    transform: scale(1.12);
    box-shadow: 0 6px 14px rgba(26,58,92,0.35);
}

.tradeex-sim-step.is-active .tradeex-sim-step-label {
    color: #1a3a5c;
}

.tradeex-sim-step.is-done .tradeex-sim-step-dot {
    background: #27ae60;
    border-color: #27ae60;
    color: #fff;
}

.tradeex-sim-step.is-done .tradeex-sim-step-label {
    color: #27ae60;
}

.tradeex-sim-period-counter {
    text-align: center;
    font-size: 1.15rem;
    margin-bottom: 24px;
    color: #1a3a5c;
    font-weight: 600;
}

.tradeex-sim-period-counter span#currentDay {
    display: inline-block;
    min-width: 30px;
    padding: 2px 10px;
    background: #1a3a5c;
    color: #fff;
    border-radius: 8px;
    margin: 0 2px;
}

.tradeex-sim-status-cards {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 18px;
    margin-bottom: 28px;
}

.tradeex-sim-status-card {
    background: white;
    border-radius: 16px;
    padding: 22px 18px;
    box-shadow: 0 6px 18px rgba(26,58,92,0.08);
    transition: transform 0.3s ease, box-shadow 0.3s ease;
    text-align: center;
    border-top: 4px solid #2c5f8a;
}

.tradeex-sim-status-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 12px 26px rgba(26,58,92,0.16);
}

.tradeex-sim-label {
    color: #6a7d92;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    margin-bottom: 8px;
    font-weight: 600;
}

.tradeex-sim-value {
    font-size: 1.85rem;
    font-weight: 700;
    color: #1a3a5c;
}

.tradeex-sim-briefing {
    background: white;
    border-left: 5px solid #2c5f8a;
    border-radius: 14px;
    padding: 26px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(26,58,92,0.06);
}

.tradeex-sim-briefing h3 {
    color: #1a3a5c;
    margin-top: 0;
    margin-bottom: 14px;
    font-size: 1.2rem;
}

.tradeex-sim-briefing-text {
    color: #44505d;
    line-height: 1.75;
    font-size: 0.97rem;
}

.tradeex-sim-briefing-text b {
    color: #1a3a5c;
}

.tradeex-sim-controls {
    background: white;
    border-radius: 16px;
    padding: 28px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(26,58,92,0.06);
}

.tradeex-sim-controls h3 {
    color: #1a3a5c;
    margin-top: 0;
    margin-bottom: 22px;
    font-size: 1.2rem;
    padding-bottom: 12px;
    border-bottom: 2px solid #eef2f7;
}

.tradeex-sim-input-group {
    margin-bottom: 20px;
}

.tradeex-sim-input-group label {
    display: block;
    font-weight: 600;
    color: #2c3e50;
    margin-bottom: 7px;
    font-size: 0.92rem;
}

.tradeex-sim-input-group select {
    max-width: 520px;
    width: 100%;
    padding: 10px 12px;
    border: 1.5px solid #d5dfea;
    border-radius: 10px;
    font-size: 0.95rem;
    background: #fbfcfe;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.tradeex-sim-input-group select:focus {
    outline: none;
    border-color: #2c5f8a;
    box-shadow: 0 0 0 3px rgba(44,95,138,0.15);
}

.tradeex-sim-checkbox-group {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 8px;
    background: #f6f9fc;
    border-radius: 10px;
    border: 1px solid #e6edf4;
}

.tradeex-sim-checkbox {
    display: flex;
    align-items: center;
    gap: 10px;
    font-weight: 400 !important;
    cursor: pointer;
    margin-bottom: 0;
    padding: 9px 10px;
    border-radius: 8px;
    transition: background 0.2s ease;
}

.tradeex-sim-checkbox:hover {
    background: #eaf1f8;
}

.tradeex-sim-checkbox input[type="checkbox"] {
    width: 18px;
    height: 18px;
    accent-color: #2c5f8a;
    flex-shrink: 0;
}

.tradeex-sim-submit {
    margin-top: 18px;
    padding: 13px 44px;
    font-size: 1.05rem;
    font-weight: 600;
    border-radius: 12px;
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    border: none;
    color: #fff;
    box-shadow: 0 8px 18px rgba(26,58,92,0.28);
    transition: transform 0.2s ease, box-shadow 0.2s ease, background 0.3s ease;
}

.tradeex-sim-submit:hover {
    background: linear-gradient(135deg, #0f2a45 0%, #1a4a70 100%);
    transform: translateY(-2px);
    box-shadow: 0 12px 24px rgba(26,58,92,0.34);
}

.tradeex-sim-undo {
    margin-top: 12px;
    margin-left: 12px;
    border-radius: 10px;
}

.tradeex-sim-results {
    background: linear-gradient(135deg, #f0f9f3 0%, #e8f5ee 100%);
    border-left: 5px solid #27ae60;
    border-radius: 14px;
    padding: 26px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(39,174,96,0.10);
    animation: tradeexFadeIn 0.4s ease;
}

.tradeex-sim-results h4 {
    color: #1e8c4e;
    margin-top: 0;
    font-size: 1.15rem;
}

.tradeex-sim-results-text {
    color: #2c3e50;
    line-height: 1.8;
    font-size: 0.96rem;
}

.tradeex-sim-history {
    margin-bottom: 24px;
    background: white;
    border-radius: 14px;
    padding: 8px 16px;
    box-shadow: 0 6px 18px rgba(26,58,92,0.06);
    overflow-x: auto;
}

.tradeex-sim-history table {
    margin-bottom: 0;
}

.tradeex-sim-charts {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(350px, 1fr));
    gap: 20px;
    margin-bottom: 30px;
}

.tradeex-sim-chart-wrapper {
    background: white;
    border-radius: 16px;
    padding: 20px;
    box-shadow: 0 6px 18px rgba(26,58,92,0.06);
    min-height: 300px;
}

/* ---- Round-end modal ---- */
.tradeex-sim-modal-overlay {
    display: none;
    position: fixed;
    inset: 0;
    background: rgba(15,30,50,0.55);
    backdrop-filter: blur(4px);
    z-index: 9999;
    align-items: center;
    justify-content: center;
    padding: 20px;
}

.tradeex-sim-modal-overlay.is-open {
    display: flex;
    animation: tradeexFadeIn 0.25s ease;
}

.tradeex-sim-modal {
    background: #fff;
    border-radius: 18px;
    width: 100%;
    max-width: 540px;
    max-height: 88vh;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    box-shadow: 0 24px 60px rgba(0,0,0,0.35);
    animation: tradeexModalPop 0.32s cubic-bezier(0.16, 1, 0.3, 1);
}

.tradeex-sim-modal-header {
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    color: #fff;
    padding: 22px 26px;
    display: flex;
    align-items: center;
    gap: 14px;
}

.tradeex-sim-modal-header h3 {
    margin: 0;
    font-size: 1.25rem;
    font-weight: 700;
}

.tradeex-sim-modal-icon {
    width: 42px;
    height: 42px;
    border-radius: 50%;
    background: rgba(255,255,255,0.18);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.3rem;
    flex-shrink: 0;
}

.tradeex-sim-modal.is-final .tradeex-sim-modal-header {
    background: linear-gradient(135deg, #1e8c4e 0%, #27ae60 100%);
}

.tradeex-sim-modal-body {
    padding: 24px 26px;
    overflow-y: auto;
    color: #2c3e50;
    line-height: 1.8;
    font-size: 0.96rem;
}

.tradeex-sim-modal-body b {
    color: #1a3a5c;
}

.tradeex-sim-modal-row {
    display: flex;
    justify-content: space-between;
    gap: 14px;
    padding: 9px 0;
    border-bottom: 1px solid #eef2f7;
}

.tradeex-sim-modal-row:last-child {
    border-bottom: none;
}

.tradeex-sim-modal-row .k {
    color: #6a7d92;
    font-weight: 600;
}

.tradeex-sim-modal-row .v {
    color: #1a3a5c;
    font-weight: 700;
    text-align: right;
}

.tradeex-sim-modal-row .v.neg {
    color: #c0392b;
}

.tradeex-sim-modal-warn {
    background: #fff4e5;
    border-left: 4px solid #e67e22;
    color: #a85b10;
    padding: 11px 14px;
    border-radius: 8px;
    margin-top: 14px;
    font-size: 0.9rem;
}

.tradeex-sim-modal-score {
    text-align: center;
    margin-top: 18px;
    padding-top: 16px;
    border-top: 2px dashed #d5dfea;
}

.tradeex-sim-modal-score .big {
    font-size: 2.4rem;
    font-weight: 800;
    color: #1a3a5c;
    line-height: 1;
}

.tradeex-sim-modal-score .big small {
    font-size: 1.1rem;
    color: #90a4bd;
    font-weight: 600;
}

.tradeex-sim-modal-footer {
    padding: 16px 26px 22px 26px;
    text-align: right;
    border-top: 1px solid #eef2f7;
}

.tradeex-sim-modal-btn {
    padding: 11px 34px;
    font-weight: 600;
    border-radius: 11px;
    background: linear-gradient(135deg, #1a3a5c 0%, #2c5f8a 100%);
    border: none;
    color: #fff;
    box-shadow: 0 6px 14px rgba(26,58,92,0.25);
    transition: transform 0.2s ease;
}

.tradeex-sim-modal-btn:hover {
    transform: translateY(-2px);
    color: #fff;
}

@keyframes tradeexFadeIn {
    from { opacity: 0; }
    to { opacity: 1; }
}

@keyframes tradeexModalPop {
    from { opacity: 0; transform: translateY(24px) scale(0.96); }
    to { opacity: 1; transform: translateY(0) scale(1); }
}

@media (max-width: 768px) {
    .tradeex-sim-status-cards {
        grid-template-columns: repeat(2, 1fr);
    }
    .tradeex-sim-charts {
        grid-template-columns: 1fr;
    }
    .tradeex-sim-header h1 {
        font-size: 1.4rem;
    }
    .tradeex-sim-step-label {
        font-size: 0.68rem;
    }
    .tradeex-sim-step-dot {
        width: 32px;
        height: 32px;
        font-size: 0.85rem;
    }
}

