(function() {
    'use strict';

    class TradeexAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'TRADEEX: Trade Finance & Export Strategy';
            this.version = '1.2.0';

            this.ORDER_VOLUME_MT = 120;
            this.ORDER_PRICE_FOB = 3200;
            this.ORDER_VALUE = 384000;
            this.CONTAINER_CAPACITY = 24;
            this.CONTAINERS_NEEDED = 5;

            this.BASE_COST_PER_MT = 2160;


        }

        _lang() {
            try {
                var s = window.mySimulation;
                if (s && s.language) return s.language;
                if (s && s.currentLanguage) return s.currentLanguage;
                var hl = (document.documentElement && document.documentElement.lang) || '';
                if (hl) return hl.slice(0, 2).toLowerCase();
            } catch (e) {}
            return 'en';
        }

        _t(key) {
            try {
                if (window.mySimulation && typeof window.mySimulation.t === 'function') return window.mySimulation.t(key);
            } catch (e) {}
            return key;
        }

        _money(v) {
            return '$' + Math.round(v || 0).toLocaleString();
        }

        _payName(code) {
            var map = {
                open_account: 'opt_open_account',
                dp_collection: 'opt_dp',
                da_collection: 'opt_da',
                lc_unconfirmed: 'opt_lc_unconfirmed',
                lc_confirmed: 'opt_lc_confirmed'
            };
            return map[code] ? this._t(map[code]) : (code || '');
        }

        _financingName(code) {
            var map = {
                self_finance: 'opt_self_finance',
                bank_loan: 'opt_bank_loan',
                factoring: 'opt_factoring',
                supplier_credit: 'opt_supplier_credit'
            };
            return map[code] ? this._t(map[code]) : (code || '');
        }

        _hedgingName(code) {
            var map = { unhedged: 'opt_unhedged', put_option: 'opt_put_option', forward: 'opt_forward' };
            return map[code] ? this._t(map[code]) : (code || '');
        }

        _resolutionName(code) {
            var map = { waiver: 'opt_waiver', re_present: 'opt_re_present', under_reserve: 'opt_under_reserve' };
            return map[code] ? this._t(map[code]) : (code || '');
        }

        _frameworkName(code) {
            var map = { accept: 'opt_accept', counter: 'opt_counter', decline: 'opt_decline' };
            return map[code] ? this._t(map[code]) : (code || '');
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 280000,
                    orderValue: 384000,
                    netMargin: 0,
                    netMarginPct: 0,
                    totalCosts: 0,
                    totalDeductions: 0,
                    financialMarginScore: 0,
                    riskScore: 0,
                    documentaryScore: 0,
                    strategicScore: 0,
                    executionScore: 0,
                    totalScore: 0,
                    paymentInstrument: '',
                    incoterm: '',
                    isCIF: false,
                    financingChoice: '',
                    forwarderChoice: '',
                    hedgingChoice: '',
                    discrepanciesFound: 0,
                    discrepanciesMissed: 0,
                    resolutionChoice: '',
                    frameworkChoice: '',
                    hasInsurance: false,
                    lcConfirmationFee: 0,
                    financingCost: 0,
                    freightCost: 0,
                    insuranceCost: 0,
                    fxLoss: 0,
                    hedgingCost: 0,
                    discrepancyPenalty: 0,
                    amendmentFees: 0,
                    scoreHistory: [],
                    costHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    round: 1
                };
            }
            this._wireModal();
            this._updateBriefing(state);
        }

        _wireModal() {
            var self = this;
            var closeBtn = document.getElementById('roundModalClose');
            var overlay = document.getElementById('roundModalOverlay');
            if (closeBtn && !closeBtn._tradeexBound) {
                closeBtn._tradeexBound = true;
                closeBtn.addEventListener('click', function() { self._closeModal(); });
            }
            if (overlay && !overlay._tradeexBound) {
                overlay._tradeexBound = true;
                overlay.addEventListener('click', function(e) {
                    if (e.target === overlay) self._closeModal();
                });
            }
        }

        _updateStepper(round) {
            var steps = document.querySelectorAll('.tradeex-sim-step');
            for (var i = 0; i < steps.length; i++) {
                var n = i + 1;
                steps[i].classList.remove('is-active', 'is-done');
                if (n < round) steps[i].classList.add('is-done');
                else if (n === round) steps[i].classList.add('is-active');
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, 3);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = this._t('brief' + (idx + 1));

            var r1 = document.getElementById('round1Panel');
            var r2 = document.getElementById('round2Panel');
            var r3 = document.getElementById('round3Panel');
            var r4 = document.getElementById('round4Panel');
            var round = (state.currentPeriod || 1);

            this._updateStepper(round);

            if (r1) r1.style.display = round === 1 ? 'block' : 'none';
            if (r2) r2.style.display = round === 2 ? 'block' : 'none';
            if (r3) r3.style.display = round === 3 ? 'block' : 'none';
            if (r4) r4.style.display = round === 4 ? 'block' : 'none';

            if (round === 2) {
                var fwdGroup = document.getElementById('forwarderGroup');
                if (fwdGroup) {
                    var ds = state.domainState || {};
                    fwdGroup.style.display = ds.isCIF ? 'block' : 'none';
                }
            }

            if (round === 3) {
                var resGroup = document.getElementById('resolutionGroup');
                if (resGroup) {
                    var ds2 = state.domainState || {};
                    var needsResolution = (ds2.discrepanciesMissed || 0) > 0;
                    resGroup.style.display = needsResolution ? 'block' : 'none';
                }
            }
        }

        validateDecisions(decisions) {
            var round = window.mySimulation.state.currentPeriod || 1;
            decisions.round = round;

            if (round === 1) {
                var payEl = document.getElementById('paymentInstrumentSelect');
                var incEl = document.getElementById('incotermSelect');
                decisions.paymentInstrument = payEl ? payEl.value : '';
                decisions.incoterm = incEl ? incEl.value : '';

                if (!decisions.paymentInstrument) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_payment'), 'warning');
                    return false;
                }
                if (!decisions.incoterm) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_incoterm'), 'warning');
                    return false;
                }
            } else if (round === 2) {
                var d1 = document.getElementById('disc1');
                var d2 = document.getElementById('disc2');
                var d3 = document.getElementById('disc3');
                var d4 = document.getElementById('disc4');
                var d5 = document.getElementById('disc5');
                decisions.disc1 = d1 ? d1.checked : false;
                decisions.disc2 = d2 ? d2.checked : false;
                decisions.disc3 = d3 ? d3.checked : false;
                decisions.disc4 = d4 ? d4.checked : false;
                decisions.disc5 = d5 ? d5.checked : false;

                var finEl = document.getElementById('financingSelect');
                decisions.financing = finEl ? finEl.value : '';

                var fwdEl = document.getElementById('forwarderSelect');
                decisions.forwarder = fwdEl ? fwdEl.value : '';

                if (!decisions.financing) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_financing'), 'warning');
                    return false;
                }
                var ds = window.mySimulation.state.domainState;
                if (ds.isCIF && !decisions.forwarder) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_forwarder'), 'warning');
                    return false;
                }
            } else if (round === 3) {
                var hedgeEl = document.getElementById('hedgingSelect');
                decisions.hedging = hedgeEl ? hedgeEl.value : '';
                var resEl = document.getElementById('resolutionSelect');
                decisions.resolution = resEl ? resEl.value : '';

                if (!decisions.hedging) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_hedging'), 'warning');
                    return false;
                }
                var ds3 = window.mySimulation.state.domainState;
                if ((ds3.discrepanciesMissed || 0) > 0 && !decisions.resolution) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_resolution'), 'warning');
                    return false;
                }
            } else if (round === 4) {
                var frmEl = document.getElementById('frameworkSelect');
                decisions.framework = frmEl ? frmEl.value : '';
                var insEl = document.getElementById('insuranceCheck');
                decisions.insurance = insEl ? insEl.checked : false;

                if (!decisions.framework) {
                    window.mySimulation.uiManager.showNotification(window.mySimulation.t('warn_framework'), 'warning');
                    return false;
                }
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var round = d.round;
            var roundScore = 0;
            var roundCost = 0;
            var resultSummary = '';

            if (round === 1) {
                ds.paymentInstrument = d.paymentInstrument;
                ds.incoterm = d.incoterm;
                ds.isCIF = (d.incoterm === 'cif');

                var payScores = { open_account: 0, dp_collection: 12, da_collection: 6, lc_unconfirmed: 18, lc_confirmed: 25 };
                ds.riskScore = payScores[d.paymentInstrument] || 0;

                if (d.paymentInstrument === 'lc_confirmed') {
                    ds.lcConfirmationFee = Math.round(ds.orderValue * 0.01);
                    roundCost += ds.lcConfirmationFee;
                }

                if (ds.isCIF) {
                    ds.freightCost = 2800 * 5;
                    var cifValue = ds.orderValue + ds.freightCost;
                    ds.insuranceCost = Math.round(cifValue * 0.0035);
                    roundCost += ds.freightCost + ds.insuranceCost;
                }

                ds.totalDeductions += roundCost;
                resultSummary = this._payName(d.paymentInstrument) + ' / ' + (d.incoterm || '').toUpperCase();
                roundScore = ds.riskScore;

            } else if (round === 2) {
                var found = 0;
                if (d.disc1) found++;
                if (d.disc2) found++;
                if (d.disc3) found++;
                if (d.disc4) found++;
                if (d.disc5) found++;
                ds.discrepanciesFound = found;
                ds.discrepanciesMissed = 5 - found;
                ds.documentaryScore = found * 4;
                ds.amendmentFees = found * 150;
                roundCost += ds.amendmentFees;

                ds.financingChoice = d.financing;
                if (d.financing === 'bank_loan') {
                    ds.financingCost = 5400;
                } else if (d.financing === 'factoring') {
                    ds.financingCost = 12288;
                } else if (d.financing === 'self_finance') {
                    ds.financingCost = 0;
                } else if (d.financing === 'supplier_credit') {
                    ds.financingCost = 0;
                }
                roundCost += ds.financingCost;

                if (ds.isCIF && d.forwarder) {
                    ds.forwarderChoice = d.forwarder;
                    var forwarderCosts = { transandes: 2650, lima_cargo: 2300, dhl: 3100 };
                    var selectedFreight = (forwarderCosts[d.forwarder] || 2650) * 5;
                    var freightDiff = selectedFreight - ds.freightCost;
                    if (freightDiff !== 0) {
                        ds.freightCost = selectedFreight;
                        roundCost += freightDiff;
                    }
                }

                ds.totalDeductions += roundCost;
                roundScore = ds.documentaryScore;
                resultSummary = found + '/5 ' + this._t('sum_disc_found');

            } else if (round === 3) {
                ds.hedgingChoice = d.hedging;

                if (d.hedging === 'unhedged') {
                    ds.fxLoss = Math.round(ds.orderValue * 0.08);
                    ds.hedgingCost = 0;
                    ds.riskScore = Math.max(0, ds.riskScore);
                } else if (d.hedging === 'put_option') {
                    ds.fxLoss = 0;
                    ds.hedgingCost = Math.round(ds.orderValue * 0.014);
                    ds.riskScore = Math.min(25, ds.riskScore + 25);
                } else if (d.hedging === 'forward') {
                    ds.fxLoss = 0;
                    ds.hedgingCost = 0;
                    ds.riskScore = Math.min(25, ds.riskScore + 25);
                }
                roundCost += ds.fxLoss + ds.hedgingCost;

                if (ds.discrepanciesMissed > 0) {
                    ds.resolutionChoice = d.resolution || 'waiver';
                    if (d.resolution === 'waiver') {
                        ds.discrepancyPenalty = 4500;
                    } else if (d.resolution === 're_present') {
                        ds.discrepancyPenalty = 2000;
                        ds.executionScore = Math.max(0, ds.executionScore - 3);
                    } else if (d.resolution === 'under_reserve') {
                        ds.discrepancyPenalty = 1500;
                        ds.riskScore = Math.max(0, ds.riskScore - 5);
                    }
                    ds.documentaryScore = Math.max(0, ds.documentaryScore - (ds.discrepanciesMissed * 3));
                    roundCost += ds.discrepancyPenalty;
                }

                ds.totalDeductions += roundCost;
                roundScore = Math.round((ds.riskScore + ds.documentaryScore) / 2);
                resultSummary = this._hedgingName(d.hedging) + (ds.discrepanciesMissed > 0 ? ' / ' + this._resolutionName(d.resolution || 'waiver') : '');

            } else if (round === 4) {
                ds.frameworkChoice = d.framework;
                ds.hasInsurance = d.insurance || false;

                if (d.framework === 'counter') {
                    ds.strategicScore = 15;
                } else if (d.framework === 'accept') {
                    ds.strategicScore = 5;
                } else if (d.framework === 'decline') {
                    ds.strategicScore = 8;
                }

                if (ds.hasInsurance) {
                    ds.riskScore = Math.min(25, ds.riskScore + 10);
                }

                ds.executionScore = Math.min(10, (ds.executionScore || 0) + 10);

                var baseCost = 2160 * 120;
                var totalDeductions = ds.lcConfirmationFee + ds.financingCost + ds.amendmentFees + ds.fxLoss + ds.hedgingCost + ds.discrepancyPenalty;
                if (ds.isCIF) {
                    totalDeductions += ds.freightCost + ds.insuranceCost;
                }
                var totalCostAll = baseCost + totalDeductions;
                ds.totalCosts = totalCostAll;
                ds.netMargin = ds.orderValue - totalCostAll;
                ds.netMarginPct = Math.round((ds.netMargin / ds.orderValue) * 1000) / 10;
                ds.cash = 280000 + ds.netMargin;

                if (ds.netMarginPct >= 12) {
                    ds.financialMarginScore = 30;
                } else if (ds.netMarginPct >= 8) {
                    ds.financialMarginScore = Math.round(15 + (ds.netMarginPct - 8) * 3.75);
                } else {
                    ds.financialMarginScore = Math.max(0, Math.round(ds.netMarginPct * 1.875));
                }

                ds.riskScore = Math.min(25, ds.riskScore);
                ds.documentaryScore = Math.min(20, ds.documentaryScore);
                ds.strategicScore = Math.min(15, ds.strategicScore);
                ds.executionScore = Math.min(10, ds.executionScore);

                ds.totalScore = ds.financialMarginScore + ds.riskScore + ds.documentaryScore + ds.strategicScore + ds.executionScore;

                roundScore = ds.totalScore;
                roundCost = totalDeductions;
                resultSummary = this._frameworkName(d.framework) + (ds.hasInsurance ? ' + ' + this._t('sum_insurance') : '');
            }

            ds.scoreHistory.push(roundScore);
            ds.costHistory.push(roundCost);

            var results = {
                period: state.currentPeriod,
                round: round,
                roundScore: roundScore,
                roundCost: roundCost,
                totalScore: ds.totalScore,
                netMargin: ds.netMargin,
                netMarginPct: ds.netMarginPct,
                summary: resultSummary
            };

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: round + 1, domainState: ds });
                self._showRoundResults(state, results);
            }, 500);

            return results;
        }

        _buildResultsHTML(state, results) {
            var ds = state.domainState;
            var round = results.round;
            var rows = [];
            var t = this._t.bind(this);

            function row(k, v, neg) {
                rows.push('<div class="tradeex-sim-modal-row"><span class="k">' + k + '</span><span class="v' + (neg ? ' neg' : '') + '">' + v + '</span></div>');
            }

            var extra = '';

            if (round === 1) {
                row(t('res_payment_instrument'), this._payName(ds.paymentInstrument));
                row(t('res_incoterm'), (ds.incoterm || '').toUpperCase());
                if (ds.lcConfirmationFee > 0) row(t('res_lc_conf_fee'), '-' + this._money(ds.lcConfirmationFee), true);
                if (ds.isCIF) {
                    row(t('res_freight_cost'), '-' + this._money(ds.freightCost), true);
                    row(t('res_marine_insurance'), '-' + this._money(ds.insuranceCost), true);
                }
                row('<b>' + t('res_risk_score') + '</b>', '<b>' + ds.riskScore + '/25</b>');
            } else if (round === 2) {
                row(t('res_disc_found'), ds.discrepanciesFound + ' / 5');
                if (ds.discrepanciesMissed > 0) {
                    extra += '<div class="tradeex-sim-modal-warn">⚠ ' + t('res_disc_warn_pre') + ' ' + ds.discrepanciesMissed + ' ' + t('res_disc_warn_post') + '</div>';
                }
                row(t('res_financing'), this._financingName(ds.financingChoice));
                if (ds.financingCost > 0) row(t('res_cost'), '-' + this._money(ds.financingCost), true);
                if (ds.amendmentFees > 0) row(t('res_amendment_fees'), '-' + this._money(ds.amendmentFees), true);
                row('<b>' + t('res_doc_score') + '</b>', '<b>' + ds.documentaryScore + '/20</b>');
            } else if (round === 3) {
                row(t('res_hedging'), this._hedgingName(ds.hedgingChoice));
                if (ds.fxLoss > 0) row(t('res_fx_loss'), '-' + this._money(ds.fxLoss), true);
                if (ds.hedgingCost > 0) row(t('res_hedging_premium'), '-' + this._money(ds.hedgingCost), true);
                if (ds.discrepancyPenalty > 0) {
                    row(t('res_resolution'), this._resolutionName(ds.resolutionChoice));
                    row(t('res_disc_penalty'), '-' + this._money(ds.discrepancyPenalty), true);
                }
            } else if (round === 4) {
                row(t('res_framework_response'), this._frameworkName(ds.frameworkChoice));
                row(t('res_credit_insurance'), ds.hasInsurance ? t('res_yes') : t('res_no'));
                extra += '<div class="tradeex-sim-modal-score">';
                extra += '<div style="font-weight:700;color:#1a3a5c;margin-bottom:10px;">' + t('res_final_scorecard') + '</div>';
                extra += '<div class="tradeex-sim-modal-row"><span class="k">' + t('res_financial_margin') + '</span><span class="v">' + ds.financialMarginScore + '/30 (' + t('res_net_margin') + ': ' + ds.netMarginPct + '%)</span></div>';
                extra += '<div class="tradeex-sim-modal-row"><span class="k">' + t('res_risk_management') + '</span><span class="v">' + ds.riskScore + '/25</span></div>';
                extra += '<div class="tradeex-sim-modal-row"><span class="k">' + t('res_doc_accuracy') + '</span><span class="v">' + ds.documentaryScore + '/20</span></div>';
                extra += '<div class="tradeex-sim-modal-row"><span class="k">' + t('res_strategic_judgment') + '</span><span class="v">' + ds.strategicScore + '/15</span></div>';
                extra += '<div class="tradeex-sim-modal-row"><span class="k">' + t('res_execution_speed') + '</span><span class="v">' + ds.executionScore + '/10</span></div>';
                extra += '<div class="big" style="margin-top:14px;">' + ds.totalScore + '<small>/100</small></div>';
                extra += '<div style="margin-top:6px;color:#6a7d92;font-weight:600;">' + t('res_net_margin') + ': ' + this._money(ds.netMargin) + ' (' + ds.netMarginPct + '%)</div>';
                extra += '</div>';
            }

            return rows.join('') + extra;
        }

        _showRoundResults(state, results) {
            var html = this._buildResultsHTML(state, results);

            var panel = document.getElementById('roundResultsPanel');
            var textEl = document.getElementById('roundResultsText');
            if (panel && textEl) {
                textEl.innerHTML = html;
                panel.style.display = 'block';
            }

            this._openModal(state, results, html);
        }

        _openModal(state, results, html) {
            var overlay = document.getElementById('roundModalOverlay');
            var body = document.getElementById('roundModalBody');
            var titleEl = document.getElementById('roundModalTitle');
            var iconEl = document.getElementById('roundModalIcon');
            var modal = overlay ? overlay.querySelector('.tradeex-sim-modal') : null;
            if (!overlay || !body) return;

            this._wireModal();

            body.innerHTML = html;

            var isFinal = results.round === 4;
            if (titleEl) {
                titleEl.textContent = isFinal ? this._t('modal_title_final') : (this._t('modal_title_round') + ' ' + results.round);
            }
            if (iconEl) iconEl.textContent = isFinal ? '🏆' : '✓';
            if (modal) {
                if (isFinal) modal.classList.add('is-final');
                else modal.classList.remove('is-final');
            }

            overlay.classList.add('is-open');
        }

        _closeModal() {
            var overlay = document.getElementById('roundModalOverlay');
            if (overlay) overlay.classList.remove('is-open');
        }

