        getPerformanceSummary(history) {
            if (!history.length) return {};
            var last = history[history.length - 1];
            var ds = last.domainState ? last.domainState : {};
            var totalScore = ds.totalScore || 0;

            var performance = this._t('perf_beginner');
            if (totalScore >= 80) performance = this._t('perf_expert');
            else if (totalScore >= 60) performance = this._t('perf_competent');
            else if (totalScore >= 40) performance = this._t('perf_developing');

            var insights = [];
            if ((ds.riskScore || 0) < 15) insights.push(this._t('insight_risk'));
            if ((ds.documentaryScore || 0) < 12) insights.push(this._t('insight_doc'));
            if ((ds.strategicScore || 0) < 10) insights.push(this._t('insight_strategic'));
            if ((ds.netMarginPct || 0) < 8) insights.push(this._t('insight_margin'));
            if (insights.length === 0) insights.push(this._t('insight_strong'));

            return {
                totalScore: totalScore,
                netMargin: ds.netMargin || 0,
                netMarginPct: ds.netMarginPct || 0,
                performance: performance,
                insights: insights
            };
        }

